mapper.select:
SELECT COUNT(*) AS count
FROM pickup_record
WHERE express_id = #{expressId}

SELECT pr.id AS id, pr.express_id AS expressId, e.express_no AS expressNo, e.receiver_name AS receiverName, pr.user_id AS userId, u.username AS username, pr.operator_id AS operatorId, ou.real_name AS operatorName, pr.pickup_code AS pickupCode, pr.pickup_method AS pickupMethod, DATE_FORMAT(pr.pickup_time, '%Y-%m-%d %H:%i:%s') AS pickupTime, pr.remark AS remark, DATE_FORMAT(pr.create_time, '%Y-%m-%d %H:%i:%s') AS createTime FROM pickup_record pr LEFT JOIN express e ON e.id = pr.express_id LEFT JOIN sys_user u ON u.id = pr.user_id LEFT JOIN sys_user ou ON ou.id = pr.operator_id WHERE pr.user_id = #{userId}
AND e.express_no LIKE CONCAT('%', #{keyword}, '%')
ORDER BY pr.id DESC

SELECT pr.id AS id, pr.express_id AS expressId, e.express_no AS expressNo, e.receiver_name AS receiverName, e.receiver_phone AS receiverPhone, pr.user_id AS userId, COALESCE(u.real_name, u.username) AS userName, u.username AS username, pr.operator_id AS operatorId, ou.real_name AS operatorName, pr.pickup_code AS pickupCode, pr.pickup_method AS pickupMethod, DATE_FORMAT(pr.pickup_time, '%Y-%m-%d %H:%i:%s') AS pickupTime, pr.remark AS remark, DATE_FORMAT(pr.create_time, '%Y-%m-%d %H:%i:%s') AS createTime FROM pickup_record pr LEFT JOIN express e ON e.id = pr.express_id LEFT JOIN sys_user u ON u.id = pr.user_id LEFT JOIN sys_user ou ON ou.id = pr.operator_id WHERE 1 = 1
AND (e.express_no LIKE CONCAT('%', #{kw}, '%') OR pr.pickup_code LIKE CONCAT('%', #{kw}, '%') OR u.username LIKE CONCAT('%', #{kw}, '%') OR u.real_name LIKE CONCAT('%', #{kw}, '%'))
AND pr.pickup_time >= #{startTime}
AND pr.pickup_time <= #{endTime}
ORDER BY pr.pickup_time DESC
